// server.js
const express = require('express');
const multer = require('multer');
const path = require('path');
const { app, server } = require('fastify')(); // Using Fastify for better async support
const { join } = require('path');
const { promises: fs } = require('fs');
const Papa = require('papaparse');
const Redis = require('ioredis');
const { Worker } = require('bullmq');

// Configuration
const BULL_PREFIX = 'csv-import';
const CSV_CHUNK_SIZE = 10000;
const CONCURRENCY = 4; // Number of parallel workers

// Setup storage
const storage = multer.diskStorage({
  destination: 'uploads/',
  filename: (req, file, cb) => cb(null, `${Date.now()}-${file.originalname}`)
});
const upload = multer({ storage });

// Redis connection
const redisConnection = new Redis({
  host: process.env.REDIS_HOST || '127.0.0.1',
  port: process.env.REDIS_PORT || 6379
});

// CSV Import Queue
const csvImportQueue = new Queue(BULL_PREFIX, {
  connection: redisConnection,
  defaultJobOptions: {
    attempts: 3,
    backoff: { type: 'exponential', delay: 5000 },
    removeOnComplete: true
  }
});

// Worker processor
new Worker(BULL_PREFIX, async job => {
  const { batch, dbConfig } = job.data;
  const client = new Client(dbConfig);

  try {
    await client.connect();
    await insertBatch(client, batch);
    await client.end();
  } catch (error) {
    await client.end();
    throw error;
  }
}, { 
  connection: redisConnection,
  concurrency: CONCURRENCY 
});

app.post('/import-customers', upload.single('csv'), async (req, res) => {
  try {
    const filePath = join(__dirname, req.file.path);
    const adminEmail = req.body.adminEmail;

    // Create job ID for tracking
    const jobId = `${Date.now()}-import`;

    // Start CSV processing pipeline
    await processCSV(filePath, req.body.dbConfig, jobId);

    // Start completion tracking
    trackImportCompletion(jobId, adminEmail);

    res.status(202).json({
      status: 'Import started in background',
      jobId,
      fileId: req.file.filename
    });
  } catch (error) {
    console.error('Import initialization failed:', error);
    res.status(500).json({ error: 'Failed to start import process' });
  }
});

// Process CSV into batches
async function processCSV(filePath, dbConfig, jobId) {
  const fileStream = fs.createReadStream(filePath);

  return new Promise((resolve, reject) => {
    let batch = [];

    Papa.parse(fileStream, {
      header: true,
      skipEmptyLines: true,
      step: async (results) => {
        batch.push(results.data);

        if (batch.length >= CSV_CHUNK_SIZE) {
          await csvImportQueue.add('csv-chunk', { 
            batch: [...batch], 
            dbConfig,
            jobId 
          });
          batch = [];
        }
      },
      complete: async () => {
        // Add remaining records
        if (batch.length > 0) {
          await csvImportQueue.add('csv-chunk', { 
            batch, 
            dbConfig,
            jobId 
          });
        }
        resolve();
      },
      error: (error) => {
        reject(error);
      }
    });
  });
}

// Track import completion
async function trackImportCompletion(jobId, adminEmail) {
  const completionKey = `${BULL_PREFIX}:${jobId}:completion`;

  const checkCompletion = async () => {
    const pending = await redisConnection.exists(`${completionKey}:pending`);
    if (!pending) {
      await sendCompletionEmail(adminEmail, true);
      await redisConnection.del(completionKey);
      return;
    }

    setTimeout(checkCompletion, 5000);
  };

  checkCompletion();
}

// Database insert helper
async function insertBatch(client, batch) {
  const columns = Object.keys(batch[0]).join(', ');
  const placeholders = batch.map((_, i) => 
    `($${i+1})`.repeat(Object.keys(batch[0]).length)
  ).join(', ');

  const values = batch.flatMap(Object.values);

  const query = `
    INSERT INTO customers (${columns})
    VALUES ${placeholders}
    ON CONFLICT (id) DO NOTHING
  `;

  await client.query(query, values);
}

// Email notification function
async function sendCompletionEmail(email, success, error = null) {
  const transporter = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: process.env.SMTP_PORT,
    auth: {
      user: process.env.SMTP_USER,
      pass: process.env.SMTP_PASS
    }
  });

  const message = {
    from: 'no-reply@company.com',
    to: email,
    subject: success ? 'Import Success' : 'Import Failed',
    text: success 
      ? 'Customer data has been successfully imported' 
      : `Import error: ${error.message}`
  };

  try {
    await transporter.sendMail(message);
  } catch (err) {
    console.error('Email notification failed:', err);
  }
}

// Initialize server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
